from pathlib import Path
from collections import Counter
import json
home=Path.home()
p=home/'Downloads'
if not p.is_dir():
    print(json.dumps({'home':str(home),'downloads_exists':False,'home_directories':[x.name for x in home.iterdir() if x.is_dir() and not x.name.startswith('.')]},ensure_ascii=False))
else:
    files=[]; dirs=[]; errors=[]; hidden=[]
    for x in p.iterdir():
        if x.name.startswith('.'):
            hidden.append(x.name)
            continue
        try:
            if x.is_symlink():
                errors.append({'name':x.name,'note':'符号链接，未跟随'})
            elif x.is_file():
                s=x.stat()
                files.append({'name':x.name,'type':x.suffix.lower() or '无扩展名','bytes':s.st_size})
            elif x.is_dir(): dirs.append(x.name)
        except OSError as e: errors.append({'name':x.name,'error':str(e)})
    print(json.dumps({'path':str(p),'scope':'仅第一层普通文件，不含隐藏项、不递归子文件夹','file_count':len(files),'type_counts':dict(sorted(Counter(x['type'] for x in files).items())),'total_bytes':sum(x['bytes'] for x in files),'largest_three':sorted(files,key=lambda x:x['bytes'],reverse=True)[:3],'files':sorted(files,key=lambda x:(x['type'],x['name'])),'folders':sorted(dirs),'hidden_excluded':len(hidden),'notes':errors},ensure_ascii=False,indent=2))

