from urllib.parse import quote
for cat,names in groups.items():
 lines.extend(['',f'### {cat}（{len(names)} 份）','',rules[cat],''])
 for name in names: lines.append(f'- [{name}]({quote(cat+"/"+name)})')
lines.extend(['','## 如何撤销','','将上述五个子文件夹中的 PDF 移回下载文件夹根目录即可恢复原摆放方式。移动前先确认根目录没有同名文件，避免覆盖。',''])
report=root/'分类说明.md'
report.write_text('\n'.join(lines),encoding='utf-8')
print('报告:',report)
print('非PDF文件保持原状:',len(nonpdf))
print('完整清单:',json.dumps(groups,ensure_ascii=False,indent=2))

