from pathlib import Path
import re,hashlib,json
root=Path.home()/'Downloads'
categories=['发票','合同','论文','说明书','其他']
patterns={
'发票':r'发票|^Invoice_|^Receipt_|收据|酒店水单',
'合同':r'合同|协议|^Service_Agreement_',
'论文':r'^2410\.05229v2\.pdf$|^Attention_Is_All_You_Need|^CRDT_survey_|^论文_',
'说明书':r'说明书|使用指南|用户手册|_manual\.pdf$|_Help_Guide\.pdf$'
}
pdfs=sorted(p for p in root.iterdir() if p.is_file() and p.suffix.lower()=='.pdf')
assert len(pdfs)==30
assert not (root/'分类说明.md').exists(), '已有分类说明，先读取再处理'
plan={cat:[] for cat in categories}
hashes={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in pdfs}
untouched={p.name:(p.stat().st_size,p.stat().st_mtime_ns) for p in root.iterdir() if p.is_file() and p.suffix.lower()!='.pdf'}
for p in pdfs:
 matches=[c for c,pat in patterns.items() if re.search(pat,p.name,re.I)]
 assert len(matches)<=1,(p.name,matches)
 plan[matches[0] if matches else '其他'].append(p.name)
for cat,names in plan.items():
 target=root/cat
 assert not target.exists(), f'目标已存在，需先检查: {target}'
 for name in names:
  assert not (target/name).exists()
print('移动前计划:',{cat:len(names) for cat,names in plan.items()})
manifest={'root':str(root),'plan':plan,'hashes':hashes,'untouched':untouched}
Path('pdf_classification_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
for cat,names in plan.items():
 target=root/cat
 target.mkdir()
 for name in names:
  (root/name).rename(target/name)
print('\n逐个子文件夹核对:')
for cat,names in plan.items():
 actual=sorted(p.name for p in (root/cat).iterdir() if p.is_file() and p.suffix.lower()=='.pdf')
 assert actual==sorted(names),(cat,actual,names)
 for name in actual:
  assert hashlib.sha256((root/cat/name).read_bytes()).hexdigest()==hashes[name],name
 print(f'{cat}: 计划 {len(names)} / 实际 {len(actual)} / 内容校验全部通过')
 print('\n'.join('  '+n for n in actual))
assert not list(root.glob('*.pdf'))
for name,stat in untouched.items():
 p=root/name
 assert (p.stat().st_size,p.stat().st_mtime_ns)==stat
print('\n总计: 30 份；下载目录根层 PDF: 0；非 PDF 文件未改动。')

