from pathlib import Path
import time, json
from datetime import datetime
folder = Path.home() / 'Downloads'
def snapshot():
    return {p.name: ('directory' if p.is_dir() else 'file') for p in folder.iterdir()}
def stamp():
    return datetime.now().astimezone().isoformat(timespec='seconds')
previous = snapshot()
start = time.monotonic()
result = {'folder': str(folder), 'baseline_time': stamp(), 'baseline_entries': previous, 'checks': []}
for i in range(1, 5):
    time.sleep(max(0, start + i * 20 - time.monotonic()))
    current = snapshot()
    result['checks'].append({'check': i, 'time': stamp(), 'elapsed_seconds': round(time.monotonic()-start, 2), 'added': sorted(current.keys()-previous.keys()), 'removed': sorted(previous.keys()-current.keys()), 'entry_count':len(current)})
    previous = current
result['finished_time'] = stamp()
print(json.dumps(result, ensure_ascii=False, indent=2))

