from pathlib import Path
from collections import defaultdict
p=Path.home()/'Downloads'
images={'.jpg','.jpeg','.png','.gif','.webp','.heic','.heif','.bmp','.tif','.tiff','.svg','.avif','.ico'}
groups=defaultdict(list)
for f in p.iterdir():
    if f.is_file():
        ext=f.suffix.lower()
        if ext=='.pdf' or ext in images:
            groups[ext].append(f.name)
print('PATH:',p)
print('PDF:',len(groups['.pdf']))
print('IMAGES:',sum(len(v) for k,v in groups.items() if k in images))
for ext,names in sorted(groups.items()):
    print(ext, len(names))
    for n in sorted(names): print('  '+n)
print('SUBFOLDERS_NOT_SCANNED:', sum(x.is_dir() for x in p.iterdir()))

