from pathlib import Path
import time, datetime, json
folder = Path.home() / 'Downloads'
if not folder.is_dir():
    raise FileNotFoundError(f'下载文件夹不存在：{folder}')
def snapshot():
    return {p.name for p in folder.iterdir()}
def now():
    return datetime.datetime.now().astimezone().isoformat(timespec='seconds')
previous = snapshot()
started = time.monotonic()
print(json.dumps({'folder': str(folder), 'baseline_time': now(), 'baseline_count': len(previous), 'baseline_entries': sorted(previous)}, ensure_ascii=False), flush=True)
for i in range(1, 5):
    time.sleep(max(0, started + 20*i - time.monotonic()))
    current = snapshot()
    print(json.dumps({'check': i, 'time': now(), 'elapsed_seconds': round(time.monotonic()-started, 2), 'count': len(current), 'added': sorted(current-previous), 'deleted': sorted(previous-current)}, ensure_ascii=False), flush=True)
    previous = current

