from pathlib import Path
import time, json
from datetime import datetime
folder=Path.home()/'Downloads'
def snapshot():
    return {p.name: ('directory' if p.is_dir() else 'file') for p in folder.iterdir()}
def now(): return datetime.now().astimezone().isoformat(timespec='seconds')
baseline=snapshot()
print(json.dumps({'phase':'baseline','time':now(),'path':str(folder),'entries':baseline},ensure_ascii=False),flush=True)
previous=baseline
start=time.monotonic()
for n in range(1,5):
    time.sleep(max(0,start+20*n-time.monotonic()))
    current=snapshot()
    added={k:current[k] for k in sorted(current.keys()-previous.keys())}
    removed={k:previous[k] for k in sorted(previous.keys()-current.keys())}
    print(json.dumps({'check':n,'time':now(),'elapsed_seconds':round(time.monotonic()-start,2),'added':added,'removed':removed,'entries':current},ensure_ascii=False),flush=True)
    previous=current
print(json.dumps({'phase':'final_comparison','added_since_baseline':{k:previous[k] for k in sorted(previous.keys()-baseline.keys())},'removed_since_baseline':{k:baseline[k] for k in sorted(baseline.keys()-previous.keys())}},ensure_ascii=False),flush=True)

