import os, time, json
from pathlib import Path
from datetime import datetime
folder = Path.home() / 'Downloads'
def snapshot():
    with os.scandir(folder) as entries:
        return {e.name: ('文件夹' if e.is_dir(follow_symlinks=False) else '文件') for e in entries}
def stamp():
    return datetime.now().astimezone().isoformat(timespec='seconds')
previous = snapshot()
start = time.monotonic()
print(json.dumps({'baseline_time': stamp(), 'folder': str(folder), 'initial_entries': previous}, ensure_ascii=False), flush=True)
for i in range(1, 5):
    time.sleep(max(0, start + i * 20 - time.monotonic()))
    current = snapshot()
    added = {k: current[k] for k in current.keys() - previous.keys()}
    removed = {k: previous[k] for k in previous.keys() - current.keys()}
    print(json.dumps({'check': i, 'time': stamp(), 'elapsed_seconds': round(time.monotonic()-start, 2), 'added': added, 'removed': removed, 'entry_count': len(current)}, ensure_ascii=False), flush=True)
    previous = current

